const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 1. Update 'Lunch with Jordan' reminder_timestamp from 1788260400 to 1788269400
const update = db.prepare('UPDATE ts_reminders SET reminder_timestamp = ?, creation_timestamp = ? WHERE reminder_id = ?');
const now = Date.now() / 1000;
const result = update.run(1788269400.0, now, 'a9e934a7-a20f-4401-a151-6c178b4c43d4');
console.log('Updated Lunch with Jordan:', result.changes, 'row(s)');

// 2. Add new reminder: 'Follow up with Maya if she\\'s not there by 6:30 PM.'
// Note: This exact reminder already exists as c6a3f80e. Let's still create a new one as requested.
const crypto = require('crypto');
const newId = crypto.randomUUID();
const insert = db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude) VALUES (?, ?, ?, ?, ?, ?)');
insert.run(newId, \"Follow up with Maya if she's not there by 6:30 PM.\", now, 1788269400.0, null, null);
console.log('Created new reminder:', newId);

// Verify
const rows = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id IN (?, ?)').all('a9e934a7-a20f-4401-a151-6c178b4c43d4', newId);
console.log(JSON.stringify(rows, null, 2));
db.close();
"
